## 🔄 ERROR HANDLING PATTERNS

### Platform Error Transformation

Convert platform-specific errors to structured Effect errors:

```typescript
// packages/platform-node-shared/src/internal/utils.ts
export const handleErrnoException =
  (module: string, method: string) => (err: NodeJS.ErrnoException, args: Array<any>): PlatformError.PlatformError => {
    switch (err.code) {
      case "ENOENT":
        return new PlatformError.SystemError({
          module,
          method,
          reason: "NotFound",
          pathOrDescriptor: args[0],
          cause: err
        })

      case "EACCES":
        return new PlatformError.SystemError({
          module,
          method,
          reason: "PermissionDenied",
          pathOrDescriptor: args[0],
          cause: err
        })

      case "EEXIST":
        return new PlatformError.SystemError({
          module,
          method,
          reason: "AlreadyExists",
          pathOrDescriptor: args[0],
          cause: err
        })

      default:
        return new PlatformError.SystemError({
          module,
          method,
          reason: "Unknown",
          pathOrDescriptor: args[0],
          syscall: err.syscall,
          cause: err
        })
    }
  }

// Usage with effectify (from effect/Effect)
import { effectify } from "effect/Effect"

const nodeAccess = effectify(
  NFS.access,
  handleErrnoException("FileSystem", "access"),
  handleBadArgument("access")
)

const nodeCopyFile = effectify(
  NFS.copyFile,
  handleErrnoException("FileSystem", "copyFile"),
  handleBadArgument("copyFile")
)

// handleBadArgument handles synchronous argument validation errors
const handleBadArgument = (method: string) => (err: unknown) =>
  new PlatformError.BadArgument({
    module: "FileSystem",
    method
  })
