import { describe, expect, it } from "vitest"

it("wrong pattern", () => {
  const result = Effect.runSync(Effect.gen(function*() {
    return yield* someEffect
  }))
  expect(result).toBe(value) // Wrong assertion method
})

// ✅ CORRECT - Use it.effect instead
